fail = 0
texts = {}
def get(f):
    if f not in texts: texts[f] = open(f).read()
    return texts[f]
for f, o, n, k in E:
    c = get(f).count(o)
    if c != k: print("MISS", f, c, o[:70]); fail += 1
    else: texts[f] = get(f).replace(o, n)
for o, n in LEG:
    hits = 0
    for f in ("legends.tex", "supplementary_legends.tex"):
        c = get(f).count(o); hits += c
        if c: texts[f] = get(f).replace(o, n); print("legend", f, c)
    if hits < 1: print("MISS legends", o[:70]); fail += 1
if fail: sys.exit(1)
for f, t in texts.items(): open(f, "w").write(t)
print("applied", len(E), "+", 2*len(LEG))
